INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 6, 'theory', 'Quiz: strings');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 0, 'What does "привет".len() return?', '["6", "12", "2", "an error: strings have no len"]', 1, 'len counts bytes in UTF-8: each Russian letter takes 2 bytes. The number of characters comes from chars().count().');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 1, 'Why can''t you write s[0] for a string?', '["Rust has no indexing at all", "it is too slow", "indexing works only for String, not &str", "a character may take several bytes, and the index would land in the middle of it"]', 3, 'Take the n-th character with s.chars().nth(n), or slice at character boundaries.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 2, 'How does String differ from &str?', '["String is owned by the program and can grow, &str is a reference to someone else''s text", "they don''t, they are synonyms", "&str can be changed, String cannot", "String is stored only on the stack"]', 0, 'String lives on the heap and can be changed (push_str); &str is read-only.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 3, 'How do you join two texts without losing either of them?', '["s1 + s2", "s1 += s2 always works for &str", "with a macro: format!(\"{}{}\", s1, s2)", "call join on a number"]', 2, 'format! takes nothing and works like an f-string. The + operator consumes the left string.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 6, 4, 'What does "1, 2, 3".split('','') do?', '["returns a vector of numbers", "returns an iterator over the pieces «1», « 2», « 3»", "changes the original string right away", "panics"]', 1, 'split returns an iterator over substrings; to get numbers, add trim, parse and collect.');
